const uid=()=>crypto.randomUUID();
let revision=0, pendingSnapshot=null, savingPromise=null, saveState="saved", conflict=false,authExpired=false;
let month=today().slice(0,7),view='dashboard',filter='all',storageOK=true;
let data=emptyData();
let incomeYear=Number(today().slice(0,4)),annualExcluded=new Set(),annualSelectionYear=Number(today().slice(0,4)),salaryExcluded=new Set(),selectionMonth=month;
const adminState={users:[],selectedId:null,query:'',page:1,loading:false,error:''};
