const place=id=>data.places.find(p=>p.id===id);
const mlabel=()=>`${Number(month.slice(0,4))}년 ${Number(month.slice(5))}월`;
function persist(){data=validateData(data);pendingSnapshot=structuredClone(data);saveState='saving';render();void flushChanges();}
function updateSaveStatus(){document.querySelectorAll('[data-save-status]').forEach(el=>{el.textContent=saveState==='saved'?(localMode?'이 브라우저에 저장됨':'내 계정에 저장됨'):saveState==='saving'?'저장 중…':'저장되지 않은 변경 있음';});const error=$('#save-error');if(error){error.hidden=saveState!=='error';error.querySelector('span').textContent=authExpired?'로그인이 만료되어 저장하지 못했습니다. 먼저 백업한 뒤 새로고침하고 다시 로그인해 주세요.':conflict?'다른 창의 기록이 변경되었습니다. 현재 기록을 백업한 뒤 새로고침해 주세요.':(localMode?'브라우저에 저장하지 못했습니다. 저장 공간을 확인하고 백업을 내려받아 주세요.':'서버에 저장하지 못했습니다. 연결을 확인하고 다시 저장하거나 백업을 내려받아 주세요.');error.querySelector('[data-retry-save]').hidden=conflict;}}
async function flushChanges(){
 if(savingPromise)return savingPromise;if(conflict||!pendingSnapshot)return;
 savingPromise=(async()=>{while(pendingSnapshot){const snapshot=pendingSnapshot;pendingSnapshot=null;saveState='saving';updateSaveStatus();try{const result=await api('/api/workspace','PUT',{data:snapshot,revision});revision=result.revision;saveState=pendingSnapshot?'saving':'saved';}catch(err){pendingSnapshot=pendingSnapshot||snapshot;saveState='error';conflict=err.status===409;authExpired=err.status===401;toast(err.message);break;}}})();
 try{await savingPromise;}finally{savingPromise=null;updateSaveStatus();}
}
let toastTimer;
