function render(){if(!currentUser)return;if(annualSelectionYear!==incomeYear){annualExcluded.clear();annualSelectionYear=incomeYear;}if(selectionMonth!==month){salaryExcluded.clear();selectionMonth=month;}const selection=selectedMonthIncome(data,month,salaryExcluded);let rr=view==='dashboard'?[...selection.records].sort((a,b)=>b.date.localeCompare(a.date)||b.start.localeCompare(a.start)):rows(),total=rr.reduce((s,r)=>s+pay(r),0),adjust=data.adjustments[month]||{allowance:0,deduction:0},net=Math.round(total)+adjust.allowance-adjust.deduction,forecast=Math.round(monthForecastPay(data,month))+adjust.allowance-adjust.deduction;if(view==='dashboard'){adjust=selection.adjust;net=selection.net;forecast=selection.forecast;}const names={profile:'내 정보',backup:'백업·복구',annual:'연간 소득',dashboard:'월간 현황',records:'근무 기록',places:'근무지 관리',salary:'급여 상세',admin:'회원 관리'};
$('#app').innerHTML=`<aside><a href="/" class="brand"><img src="/favicon.svg" alt="">월급하루<span>.</span></a><p class="tagline">당신의 하루가 월급이 되는 곳</p><p class="navlabel">MY WORKSPACE</p><nav>${[['dashboard','grid','월간 현황'],['records','calendar','근무 기록'],['salary','wallet','급여 상세'],['annual','list','연간 소득'],['places','building','근무지 관리'],['backup','download','백업·복구'],...(localMode?[['profile','list','내 정보']]:[])].map(([id,icon,title])=>`<button class="${view===id?'active':''}" data-view="${id}">${ico(icon)}${title}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="little-card">${ico('leaf')}<b>차곡차곡, 나의 하루</b><p>오늘의 작은 기록이 모여<br>한 달의 든든한 월급이 돼요.</p></div><p class="saved">${localMode?'기록은 이 브라우저에 암호화해 저장':'계정별 기록을 서버에 저장'}</p></div></aside><main><header class="topbar"><div class="crumb">나의 워크스페이스 <span style="margin-left:12px;color:#c3c9bc">/</span><strong>${names[view]}</strong></div><div class="mobile-brand"><img src="/favicon.svg" alt="">월급하루.</div><div class="topright"><span>${today().replaceAll('-','. ')}</span><span class="account-name">${esc(currentUser.name)}님</span><span class="avatar">${esc(currentUser.name.slice(0,1))}</span><button class="ghost" data-logout>로그아웃</button></div></header><div class="content"><div class="account-status"><span>나의 월급 기록</span><span data-save-status>${saveState==='saved'?(localMode?'이 브라우저에 저장됨':'내 계정에 저장됨'):'저장 중…'}</span></div><div id="save-error" class="sample save-warning" ${saveState==='error'?'':'hidden'}><span>저장되지 않은 변경 사항이 있습니다.</span><button data-retry-save>다시 저장</button><button data-action="backup">백업</button></div><section class="intro"><div><p class="eyebrow">A LITTLE RECORD, A REWARDING DAY</p><h1>${view==='profile'?'내 정보를 관리하세요.':view==='backup'?'나의 기록을 안전하게.':view==='annual'?'한 해의 소득을 한눈에.':view==='admin'?'회원 관리':view==='dashboard'?'하루의 기록, 한 달의 월급.':view==='records'?'차곡차곡 쌓이는 나의 근무.':view==='places'?'일하는 곳마다, 나의 기준으로.':'이번 달 월급, 꼼꼼하게.'}</h1><p class="subtitle">${view==='profile'?'이름·아이디·비밀번호를 변경할 수 있습니다.':view==='backup'?'백업 파일을 보관하고, 필요할 때 다시 불러오세요.':view==='annual'?'연도를 선택해 월별·근무지별 소득을 확인하세요.':view==='admin'?'회원을 검색하고 선택해 비밀번호를 초기화하세요.':view==='dashboard'?'열심히 보낸 시간을 모아, 이번 달의 월급을 확인하세요.':view==='records'?'근무한 날과 시간을 기록하면 급여가 함께 계산됩니다.':view==='places'?'근무지별 시급과 기본 근무시간을 설정하세요.':'근무 기록에 따른 기본 급여와 추가 수당·공제를 확인하세요.'}</p></div><div class="intro-actions" ${['admin','backup','profile'].includes(view)?'hidden':''}><button data-action="today">${ico('check')}오늘 출근</button><button class="primary" data-action="${view==='places'?'add-place':'add-record'}">${ico('plus')}${view==='places'?'근무지 추가':'근무 기록'}</button></div></section>${data.sample?'<div class="sample"><b>둘러보기</b><span>가상 샘플로 채워진 화면이에요.</span><button data-action="start-own">내 기록 시작하기 ↗</button></div>':''}
${view==='dashboard'?`<section class="overview"><div class="salary-card"><div class="salary-head"><span>현재까지 근무한 급여</span><span>${mlabel()}</span></div><h2>${won(net)}<small>원</small></h2><p>${selection.partial?'선택한 근무지 기본 급여 · 월 수당·공제 제외':'기록한 실제 근무 기준 · 수당 및 공제 반영'}</p><div class="salary-breakdown"><div>기본 급여<strong>${won(total)}원</strong></div><div>추가 수당<strong>+ ${won(adjust.allowance)}원</strong></div><div>공제 금액<strong>− ${won(adjust.deduction)}원</strong></div></div><div class="salary-forecast"><span>이번 달 예상 급여</span><strong>${won(forecast)}<small>원</small></strong></div></div><div class="stats-wrap"><article class="stat"><div class="stat-label">근무한 날${ico('calendar')}</div><strong>${new Set(rr.map(r=>r.date)).size}<small>일</small></strong><p>이번 달 기록 기준</p></article><article class="stat"><div class="stat-label">총 근무시간${ico('clock')}</div><strong>${hrs(rr.filter(isWorked).reduce((s,r)=>s+hours(r),0))}<small>시간</small></strong><p>무급 휴게시간 제외</p></article><div class="stat mini"><span class="round-icon">${ico('leaf')}</span><p><b>오늘도 수고한 나에게, 든든한 기록 하나.</b>캘린더의 날짜를 눌러 근무를 기록해 보세요.</p></div></div></section><div class="columns">${calendar()}${placePanel(data.records.filter(r=>r.date.startsWith(month)),data.records.filter(r=>r.date.startsWith(month)).reduce((s,r)=>s+pay(r),0),true)}</div>`:''}
${view==='records'?`<div class="view-toolbar">${picker()}<select aria-label="근무지 필터" id="place-filter"><option value="all">전체 근무지</option>${data.places.map(p=>`<option value="${p.id}" ${filter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button data-action="csv">${ico('download')}CSV</button></div><section class="panel"><div class="panel-header"><h2>근무 내역 <span style="color:#93a17e;font-weight:400">${rr.length}건</span></h2><span style="font-size:11px;color:#839176">${hrs(rr.filter(isWorked).reduce((s,r)=>s+hours(r),0))}시간 · ${won(total)}원</span></div>${recordTable(rr)}</section><section class="panel backup"><span>모든 근무기록을 백업하고, 이전 월급하루 백업 파일도 가져올 수 있어요.</span><div class="buttons"><button data-action="backup">백업 내보내기</button><button data-action="restore">백업 가져오기</button></div><input type="file" id="restore-file" accept="application/json,.json" hidden></section>`:''}
${view==='places'?`<div class="view-toolbar">${picker()}<span class="section-note">선택한 달의 근무지 · ${monthPlaces().length}곳</span><button data-action="all-places">전체 근무지 관리</button></div>${holidayNotice()}<section class="manage-grid">${monthPlaces().map(p=>`<article class="panel manage-card"><div class="place-top"><span class="place-icon">${ico('building')}</span><div><h2>${esc(p.name)}</h2><small>${esc(p.location)||'활동장소 미설정'}</small></div></div><strong>${won(p.rate)}<small style="font-size:12px;color:#8a997b"> 원 / 시간</small></strong><p>${esc(scheduleLabel(p))}${p.skipHolidays?' · 공휴일 쉼':''}<br>기본 근무 ${p.start} – ${p.end}<br>무급 휴게 ${p.break}분 · ${data.records.filter(r=>r.place===p.id&&r.date.startsWith(month)).length}개의 근무 기록</p><div class="buttons"><button data-edit-place="${p.id}">근무지 수정</button><button class="primary" data-add-at="${p.id}">근무 기록하기</button></div></article>`).join('')||'<div class="panel blank">선택한 달에 근무하는 장소가 없어요.<br>근무지를 추가하거나 전체 근무지 관리에서 일정을 설정하세요.</div>'}</section><p class="section-note" style="padding:20px 0">시급 변경은 새 기록부터 적용됩니다. 이전 기록의 시급은 기록 수정에서 변경할 수 있습니다.</p>`:''}
${view==='salary'?`<div class="view-toolbar">${picker()}<button data-action="csv" style="margin-left:auto">${ico('download')}급여 내역 CSV</button></div><div class="columns">${placePanel(rr,total)}<section class="panel"><div class="panel-header"><h2>이번 달 급여 계산</h2><button data-action="adjust">수당·공제 설정</button></div><div class="summary-line"><span>기본 급여</span><strong>${won(total)}원</strong></div><div class="summary-line"><span>추가 수당</span><strong>+ ${won(adjust.allowance)}원</strong></div><div class="summary-line"><span>공제 금액</span><strong>− ${won(adjust.deduction)}원</strong></div><div class="summary-line" style="background:#edf2e7"><b>예상 수령액</b><strong>${won(net)}원</strong></div><p class="section-note" style="padding-top:18px">세금·보험료·주휴수당·연장수당은 자동 계산하지 않습니다. 적용할 금액을 수당·공제 설정에서 직접 입력하세요.</p></section></div>`:''}
${view==='profile'&&localMode?profileView():''}${view==='backup'?backupView():''}${view==='annual'?annualView(data,incomeYear,annualExcluded):''}${view==='admin'&&currentUser.isAdmin?adminShell():''}<footer class="footer"><b>월급하루. <span style="font-weight:400;margin-left:7px">하루의 가치를 담다.</span></b><span>모든 날짜는 한국 표준시 기준</span></footer></div></main>`;
updateSaveStatus();
if(view==='profile'&&localMode)bindProfile();if(view==='admin'&&currentUser.isAdmin)bindAdminShell();const annualAll=$('#annual-select-all');if(annualAll){const checked=[...document.querySelectorAll('[data-annual-place]')].filter(input=>input.checked).length;annualAll.indeterminate=checked>0&&checked<document.querySelectorAll('[data-annual-place]').length;}const all=$('#salary-select-all');if(all)all.indeterminate=salaryExcluded.size>0&&data.places.some(p=>!salaryExcluded.has(p.id));
void syncHolidays(month.slice(0,4));
}
const weekdays=['일','월','화','수','목','금','토'];
function scheduleLabel(p){const s=p.schedule;return !s?'일정 미설정':s.type==='once'?s.date+' · 하루 근무':(s.type==='monthly'?'매월 '+s.day+'일 반복':s.days.map(d=>weekdays[d]).join('·')+'요일 반복')+' · '+s.startDate+' ~ '+(s.endDate||'종료일 없음')}
function monthPlaces(){const [y,m]=month.split('-').map(Number),count=new Date(y,m,0).getDate();return data.places.filter(p=>data.records.some(r=>r.place===p.id&&r.date.startsWith(month))||Array.from({length:count},(_,i)=>month+'-'+String(i+1).padStart(2,'0')).some(date=>scheduledOn(p,date)))}
const holidayStates=new Map(),holidayRequests=new Map();
async function syncHolidays(year,force=false){year=Number(year);if(holidayRequests.has(year))return holidayRequests.get(year);const prior=holidayStates.get(year);if(!force&&prior&&Date.now()-prior.loadedAt<86400000)return;
const task=(async()=>{try{const state=await api('/api/holidays/'+year+(force?'/refresh':''),force?'POST':'GET',force?{}:undefined);if(state.available)setHolidayYear(year,state.days);holidayStates.set(year,{...state,loadedAt:Date.now()});}catch{holidayStates.set(year,{error:'서버 연결을 확인해 주세요. 휴일은 마지막 자료로 표시됩니다.',loadedAt:Date.now()});}})();holidayRequests.set(year,task);try{await task;}finally{holidayRequests.delete(year);if(currentUser&&view!=='admin'&&Number(month.slice(0,4))===year)render();}if(force)toast(holidayStates.get(year)?.error||'휴일 자료를 새로 확인했습니다.');}
function holidayNotice(){const year=Number(month.slice(0,4)),s=holidayStates.get(year);let message=!s?'공휴일 자료 확인 중…':s.checkedAt?'휴일 자동 확인 · '+new Date(s.checkedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'기본 휴일 자료 사용';if(s?.error)message+=' · '+s.error;if(!holidayYearSupported(year))message+=' · '+year+'년 자료가 아직 제공되지 않아 공휴일을 자동 제외할 수 없습니다.';return `<div class="holiday-status ${s?.error?'holiday-warning':''}">${esc(message)}<small>${localMode?'한국천문연구원 배포 자료 · 날짜 새로고침으로 최신 배포본 확인':'한국천문연구원 자료 · 하루 한 번 자동 확인 · 임시공휴일은 제공처 갱신 후 반영'}</small><button data-action="refresh-dates" ${holidayRequests.has(year)?'disabled':''}>날짜 새로고침</button></div>`}
function calendar(){let [y,m]=month.split('-').map(Number),start=new Date(y,m-1,1).getDay(),count=new Date(y,m,0).getDate();return `<section class="panel"><div class="panel-header calendar-head"><div><h2>이번 달 근무 캘린더</h2><p>근무지 타일을 눌러 출근 기록을 수정하거나 취소하세요.</p></div>${picker()}</div>${holidayNotice()}<div class="calendar"><div class="weekdays">${['일','월','화','수','목','금','토'].map(s=>`<div>${s}</div>`).join('')}</div><div class="days">${'<div class="day empty"></div>'.repeat(start)}${Array.from({length:count},(_,i)=>{let date=month+'-'+String(i+1).padStart(2,'0'),rs=data.records.filter(r=>r.date===date),plans=plannedPlaces(data,date),day=(i+start)%7;return `<div class="day ${date===today()?'today':''} ${day===0?'sunday':day===6?'saturday':''}" role="group" aria-label="${date} 근무"><button class="day-date" data-date="${date}" aria-label="${date} 근무 추가 및 조회"><span class="num">${i+1}</span></button>${holidayName(date)?`<span class="holiday-name">${esc(holidayName(date))}</span>`:''}${rs.map(r=>`<button class="calendar-place ${isWorked(r)?'':'planned'}" data-edit-record="${r.id}" aria-label="${date} ${esc(place(r.place)?.name)} 근무 수정 또는 삭제" title="${esc(place(r.place)?.location||'')}">${esc(place(r.place)?.name)}<small>${r.start}–${r.end}</small></button>`).join('')}${plans.map(p=>`<button class="calendar-place planned" data-calendar-plan="${p.id}" data-work-date="${date}" aria-label="${date} ${esc(p.name)} 근무 수정 또는 삭제" title="${esc(p.location)}">${esc(p.name)}<small>${p.start}–${p.end}</small></button>`).join('')}${rs.some(isWorked)?`<span class="hours">${hrs(rs.filter(isWorked).reduce((s,r)=>s+hours(r),0))}시간</span>`:''}</div>`}).join('')}</div></div><div class="calendar-foot"><span><i class="dot"></i>저장한 근무 <span style="margin-left:10px">● 오늘</span></span><span>타일 선택 → 수정·삭제</span></div></section>`}
function placePanel(rr,total,selectable=false){rr=rr.filter(isWorked);return `<section class="panel"><div class="panel-header"><div><h2>근무지별 급여</h2><p>일하는 곳마다 쌓인 이번 달의 기록</p></div><button class="ghost" data-view="places" aria-label="근무지 관리">↗</button></div>${selectable?'<div class="salary-selection"><label><input type="checkbox" id="salary-select-all" '+(salaryExcluded.size?'':'checked')+'> 전체 선택</label><small>선택한 근무지만 합산</small></div>':''}<div class="places">${data.places.filter(p=>Math.round(rr.filter(r=>r.place===p.id).reduce((s,r)=>s+pay(r),0))>0).map(p=>{let pr=rr.filter(r=>r.place===p.id),sum=pr.reduce((s,r)=>s+pay(r),0);return `<div class="place-item ${selectable&&salaryExcluded.has(p.id)?'salary-unselected':''}"><div class="place-top">${selectable?`<input type="checkbox" data-salary-place="${p.id}" aria-label="${esc(p.name)} 급여 계산에 포함" ${salaryExcluded.has(p.id)?'':'checked'}>`:''}<span class="place-icon">${ico('building')}</span><div><b>${esc(p.name)}</b><small>기본 시급 ${won(p.rate)}원</small></div><button data-edit-place="${p.id}" aria-label="${esc(p.name)} 수정">↗</button></div><div class="place-total"><span>${new Set(pr.map(r=>r.date)).size}일 · ${hrs(pr.reduce((s,r)=>s+hours(r),0))}시간</span><strong>${won(sum)}<small style="font-size:10px;margin-left:3px;font-weight:400">원</small></strong></div><div class="bar"><div style="width:${total?sum/total*100:0}%"></div></div></div>`}).join('')||'<div class="blank">이 달에 표시할 근무 급여가 없습니다.</div>'}</div><div class="calc-note">실제 근무시간 × 기록별 시급으로 계산합니다.<br>분 단위 합산 후 월 합계에서 원 단위 반올림합니다.<br>세금·보험료·법정 수당은 자동 반영되지 않습니다.</div></section>`}
function recordTable(rr){return rr.length?`<div class="table-wrap"><table><thead><tr><th>근무일</th><th>근무지</th><th>출근 – 퇴근</th><th>근무시간</th><th>기본 급여</th><th></th></tr></thead><tbody>${rr.map(r=>`<tr><td>${r.date.slice(5).replace('-','. ')} <span style="font-size:9px;color:#a0aa94">${['일','월','화','수','목','금','토'][new Date(r.date+'T00:00:00').getDay()]}</span></td><td><strong>${esc(place(r.place)?.name||'삭제된 근무지')}</strong><small class="record-status">${isWorked(r)?'출근 완료':'출근 전'}</small></td><td>${r.start} – ${r.end}${r.end<r.start?' <small>(익일)</small>':''}</td><td>${isWorked(r)?hrs(hours(r))+'시간':'—'}</td><td><strong>${isWorked(r)?won(pay(r))+'원':'—'}</strong></td><td><button data-edit-record="${r.id}">수정</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="blank">이번 달은 아직 빈 페이지예요.<br>첫 근무 기록을 남겨 보세요.</div>'}
const field=(label,name,type,value,extra='',full=false)=>type==='password'?`<div class="field ${full?'full':''}"><label for="password-field-${name}">${label}</label><div class="password-input"><input id="password-field-${name}" name="${name}" type="password" value="${esc(value)}" ${extra}><button type="button" class="password-toggle" data-password-toggle="password-field-${name}" data-password-label="${esc(label)}" aria-label="${esc(label)} 보기" aria-controls="password-field-${name}" aria-pressed="false">보기</button></div></div>`:`<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function modal(title,description,body,submit,onSubmit,deleteFn){const d=$('#modal');d.innerHTML=`<h2>${title}</h2><p>${description}</p><form><div class="form-grid">${body}</div><div class="error" role="alert"></div><div class="form-actions">${deleteFn?'<button type="button" class="danger" id="delete">삭제</button>':''}<button type="button" id="cancel">취소</button><button type="submit" class="primary">${submit}</button></div></form>`;$('#cancel').onclick=()=>d.close();if(deleteFn)$('#delete').onclick=deleteFn;d.querySelector('form').onsubmit=e=>{e.preventDefault();try{onSubmit(new FormData(e.target));}catch(err){d.querySelector('.error').textContent=err.message}};d.showModal()}
function close(){ $('#modal').close() }
function scheduleFields(p,blankDates=false){const s=p.schedule||{},weekly=s.type==='weekly',monthly=s.type==='monthly';return `<fieldset class="field full schedule-options"><legend>근무 일정</legend><div class="weekday-options">${[1,2,3,4,5,6,0].map(i=>`<label><input type="checkbox" name="days" value="${i}" ${weekly&&s.days.includes(i)?'checked':''}><span>${weekdays[i]}</span></label>`).join('')}<label><input type="checkbox" name="monthlyRepeat" ${monthly?'checked':''}><span>월 1회 반복</span></label><label><input type="checkbox" name="noRepeat" ${!weekly&&!monthly?'checked':''}><span>반복 없음</span></label></div></fieldset>`+'<div class="schedule-monthly field full">'+field('매월 근무일 (일)','monthDay','number',s.day||Number(today().slice(8)),'min="1" max="31" step="1"',true)+'</div><div class="schedule-recurring schedule-dates">'+field('시작일','scheduleStart','date',s.startDate||(blankDates?'':today()),'min="2000-01-01" max="2100-12-31"')+field('종료일 (선택)','scheduleEnd','date',s.endDate||'','min="2000-01-01" max="2100-12-31"')+'</div><div class="schedule-once field full">'+field('근무일','scheduleDate','date',s.date||(blankDates?'':today()),'min="2000-01-01" max="2100-12-31"',true)+'</div><p class="hint field full">요일은 여러 개 선택할 수 있어요. 월 1회 반복은 매월 같은 날짜에 표시하며 해당 날짜가 없는 달은 건너뜁니다. 반복 없음은 선택한 날짜에만 표시됩니다.</p>'}
function extraDaysFields(p){return '<div class="field full extra-days"><label for="extra-day-off">추가 휴무일 (선택)</label><div class="extra-day-picker"><input id="extra-day-off" type="date" min="2000-01-01" max="2100-12-31"><button type="button" id="add-day-off">휴무일 추가</button></div><small>임시공휴일이나 개인 휴무일을 추가하면 해당 날짜의 근무 예정을 제외합니다.</small><div id="extra-days-list">'+(p.extraDaysOff||[]).map(extraDayChip).join('')+'</div></div>'}
function extraDayChip(date){return `<span class="day-off-chip"><input type="hidden" name="extraDaysOff" value="${esc(date)}">${esc(date)}<button type="button" data-remove-day-off aria-label="${esc(date)} 휴무일 제거">×</button></span>`}
function editPlace(id){let p=place(id)||{name:'',location:'',rate:18000,start:'09:00',end:'18:00',break:60};modal(id?'근무지 수정':'새로운 근무지','반복 요일, 월 1회 또는 하루 근무 날짜와 출퇴근시간을 설정하세요.',(id?field('근무지 이름','name','text',p.name,'required maxlength="60" autocomplete="off"',true):'<div class="field full place-name-field"><label for="workplace-name">근무지 이름</label><input id="workplace-name" name="name" type="text" required maxlength="60" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="place-name-suggestions"><div id="place-name-suggestions" class="place-name-suggestions" role="listbox" aria-label="이전 근무지" hidden></div></div><p class="field full template-status" role="status" hidden></p>')+field('활동장소 (선택)','location','text',p.location,'maxlength="80"',true)+field('기본 시급 (원)','rate','number',p.rate,'required min="0" max="10000000" step="1"')+field('무급 휴게시간 (분)','break','number',p.break,'required min="0" max="1439" step="1"')+field('기본 출근시간','start','time',p.start,'required')+field('기본 퇴근시간','end','time',p.end,'required')+scheduleFields(p,!id)+`<div class="field full holiday-option"><label class="weekday-options"><input type="checkbox" name="skipHolidays" role="switch" ${p.skipHolidays?'checked':''}><span>공휴일 쉬기</span></label><small>켜면 공휴일·대체공휴일의 근무 예정을 제외합니다.<br>접속 시 자동 확인 · 임시공휴일은 제공처 갱신 후 반영됩니다.<br>일요일은 선택한 요일을 따르며, 실제 근무기록은 유지됩니다.</small></div>`+extraDaysFields(p),'저장하기',f=>{const type=f.has('monthlyRepeat')?'monthly':f.getAll('days').length?'weekly':'once',schedule=validateSchedule(type==='monthly'?{type,day:Number(f.get('monthDay')),startDate:f.get('scheduleStart'),endDate:f.get('scheduleEnd')}:type==='weekly'?{type,days:f.getAll('days').map(Number),startDate:f.get('scheduleStart'),endDate:f.get('scheduleEnd')}:type==='once'?{type,date:f.get('scheduleDate')}:null);let next={id:id||uid(),name:f.get('name').trim(),location:f.get('location').trim(),rate:Number(f.get('rate')),break:Number(f.get('break')),start:f.get('start'),end:f.get('end'),skipHolidays:f.has('skipHolidays'),extraDaysOff:f.getAll('extraDaysOff'),...(schedule?{schedule}:{})};if(!next.name)throw Error('근무지 이름을 입력해 주세요.');if(next.skipHolidays&&schedule?.type==='once'&&holidayName(schedule.date))throw Error('선택한 날짜는 '+holidayName(schedule.date)+'입니다. 근무하려면 공휴일 쉬기를 꺼 주세요.');if(schedule?.type==='once'&&next.extraDaysOff.includes(schedule.date))throw Error('선택한 근무일이 추가 휴무일에 있습니다. 날짜를 확인해 주세요.');validateDuration(next);if(id)data.places=data.places.map(x=>x.id===id?next:x);else data.places.push(next);if(schedule&&!id)month=(schedule.type==='once'?schedule.date:schedule.startDate).slice(0,7);close();persist();toast('근무지 정보를 저장 중입니다.')},id?()=>{if(data.records.some(r=>r.place===id)){toast('근무 기록이 있는 근무지는 삭제할 수 없습니다.');return}data.places=data.places.filter(p=>p.id!==id);close();persist();toast('근무지를 삭제했습니다.')}:null);
const d=$('#modal');d.querySelector('#extra-days-list').onclick=e=>{const b=e.target.closest('[data-remove-day-off]');if(b)b.closest('.day-off-chip').remove()};d.querySelector('#add-day-off').onclick=()=>{const input=d.querySelector('#extra-day-off'),date=input.value;if(!date||!input.validity.valid){d.querySelector('.error').textContent='추가할 휴무일을 선택해 주세요.';return}const list=d.querySelector('#extra-days-list'),values=[...list.querySelectorAll('input')].map(x=>x.value);if(values.includes(date))return;if(values.length>=100){d.querySelector('.error').textContent='추가 휴무일은 최대 100개까지 등록할 수 있습니다.';return}list.insertAdjacentHTML('beforeend',extraDayChip(date));input.value='';d.querySelector('.error').textContent=''};const days=[...d.querySelectorAll('[name=days]')],none=d.querySelector('[name=noRepeat]'),monthly=d.querySelector('[name=monthlyRepeat]');const update=()=>{const type=monthly.checked?'monthly':days.some(input=>input.checked)?'weekly':'once';none.checked=type==='once';for(const group of ['recurring','monthly','once'])d.querySelectorAll('.schedule-'+group).forEach(el=>{const active=group==='recurring'?type!=='once':group===type;el.hidden=!active;el.querySelectorAll('input').forEach(input=>{input.disabled=!active;input.required=active&&['scheduleStart','scheduleDate','monthDay'].includes(input.name)})})};days.forEach(input=>input.onchange=()=>{if(input.checked)monthly.checked=false;update()});monthly.onchange=()=>{if(monthly.checked)days.forEach(input=>input.checked=false);update()};none.onchange=()=>{if(none.checked){days.forEach(input=>input.checked=false);monthly.checked=false;}update()};update();
if(!id){const name=d.querySelector('[name=name]'),list=d.querySelector('#place-name-suggestions');const hide=()=>{list.hidden=true;name.setAttribute('aria-expanded','false')};const suggestions=()=>{const query=name.value.trim().toLocaleLowerCase(),seen=new Set(),matches=[...data.places].reverse().filter(p=>{const key=p.name.trim().toLocaleLowerCase();if(seen.has(key)||!key.includes(query))return false;seen.add(key);return true}).slice(0,8);list.innerHTML=matches.map(p=>`<button type="button" role="option" aria-selected="false" data-place-suggestion="${p.id}"><b>${esc(p.name)}</b><small>${p.schedule?.type==='monthly'?'매월 '+p.schedule.day+'일 · ':p.schedule?.type==='weekly'?p.schedule.days.map(i=>weekdays[i]).join('·')+'요일 · ':''}${won(p.rate)}원/시간 · ${p.start}–${p.end}</small></button>`).join('');list.hidden=!matches.length;name.setAttribute('aria-expanded',String(!!matches.length))};name.oninput=()=>{d.querySelector('.template-status').hidden=true;suggestions()};name.onfocus=suggestions;name.onclick=suggestions;name.onblur=e=>{if(!list.contains(e.relatedTarget))hide()};name.onkeydown=e=>{if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();hide()}if(e.key==='ArrowDown'&&!list.hidden){e.preventDefault();list.querySelector('button')?.focus()}if(e.key==='Enter'&&!list.hidden){e.preventDefault();list.querySelector('button')?.click()}};list.onkeydown=e=>{const options=[...list.querySelectorAll('button')],index=options.indexOf(e.target);if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();options[(index+(e.key==='ArrowDown'?1:options.length-1))%options.length]?.focus()}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();name.focus();hide()}};list.onclick=e=>{const button=e.target.closest('[data-place-suggestion]');if(!button)return;const source=place(button.dataset.placeSuggestion);if(!source)return;for(const key of ['name','rate','start','end','break'])d.querySelector('[name='+key+']').value=source[key];monthly.checked=source.schedule?.type==='monthly';if(monthly.checked)d.querySelector('[name=monthDay]').value=source.schedule.day;days.forEach(input=>input.checked=source.schedule?.type==='weekly'&&source.schedule.days.includes(Number(input.value)));d.querySelector('[name=skipHolidays]').checked=!!source.skipHolidays;update();hide();const status=d.querySelector('.template-status');status.hidden=false;status.textContent=source.name+'의 근무조건을 불러왔습니다. 새로운 근무 날짜를 입력해 주세요.';d.querySelector(monthly.checked||days.some(input=>input.checked)?'[name=scheduleStart]':'[name=scheduleDate]').focus()};}}

function allPlaces(){const d=$('#modal');d.innerHTML='<h2>전체 근무지 관리</h2><p>다른 달의 근무지와 아직 일정이 없는 장소도 수정할 수 있어요.</p><div class="all-places">'+data.places.map(p=>`<button data-choose-place="${p.id}"><b>${esc(p.name)}</b><small>${esc(scheduleLabel(p))}</small></button>`).join('')+'</div><div class="form-actions"><button id="cancel">닫기</button></div>';$('#cancel').onclick=close;d.querySelectorAll('[data-choose-place]').forEach(b=>b.onclick=()=>{close();editPlace(b.dataset.choosePlace)});d.showModal()}
function validateDuration(r){let duration=time(r.end)-time(r.start);if(duration<0)duration+=1440;if(duration===0)throw Error('출근과 퇴근시간은 달라야 합니다.');if(r.break>=duration)throw Error('휴게시간은 전체 근무시간보다 짧아야 합니다.')}
function editRecord(id,date=today(),pid,scheduledDate=null){if(!data.places.length){toast('먼저 근무지를 추가해 주세요.');editPlace();return}let old=data.records.find(r=>r.id===id),p=place(old?.place||pid)||data.places[0],r=old||{date,place:p.id,start:p.start,end:p.end,break:p.break,rate:p.rate,note:'',status:'worked'};modal(old?(isWorked(old)?'출근 기록 수정':'출근 전 일정 수정'):scheduledDate?'이 날짜의 근무 수정':'하루의 근무 기록',scheduledDate?'수정·삭제는 이 날짜에만 적용됩니다. 저장하면 실제 근무시간과 급여에 반영됩니다.':'퇴근이 출근보다 이르면 다음 날 퇴근으로 계산합니다.',`<label class="field full">근무 상태<select name="attendanceStatus"><option value="worked" ${isWorked(r)?'selected':''}>출근 완료</option><option value="planned" ${!isWorked(r)?'selected':''}>출근 전</option></select></label>`+field('근무일','date','date',r.date,'required min="2000-01-01" max="2100-12-31"')+`<label class="field">근무지<select name="place">${data.places.map(p=>`<option value="${p.id}" ${r.place===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`+field('출근시간','start','time',r.start,'required')+field('퇴근시간','end','time',r.end,'required')+field('무급 휴게시간 (분)','break','number',r.break,'required min="0" max="1439" step="1"')+field('적용 시급 (원)','rate','number',r.rate,'required min="0" max="10000000" step="1"')+field('메모 (선택)','note','text',r.note,'maxlength="200"',true),old?'수정 저장':'근무 저장',f=>{const next={id:id||uid(),date:f.get('date'),place:f.get('place'),start:f.get('start'),end:f.get('end'),break:Number(f.get('break')),rate:Number(f.get('rate')),note:f.get('note').trim(),status:f.get('attendanceStatus')};validateDuration(next);const a=time(next.start),b=a+hours({...next,break:0})*60,base=Date.parse(next.date+'T00:00:00Z');if(data.records.some(x=>{if(x.id===id||x.place!==next.place)return false;const xa=Date.parse(x.date+'T00:00:00Z')+time(x.start)*60000,xb=xa+hours({...x,break:0})*3600000;return base+a*60000<xb&&base+b*60000>xa}))throw Error('같은 근무지의 기존 기록과 시간이 겹칩니다.');const original=old?{place:old.place,date:old.date}:scheduledDate?{place:p.id,date:scheduledDate}:null;if(original&&(original.date!==next.date||original.place!==next.place)&&scheduledOn(place(original.place),original.date))data.places=data.places.map(x=>x.id===original.place?excludeWorkDate(x,original.date):x);if(id)data.records=data.records.map(x=>x.id===id?next:x);else data.records.push(next);month=next.date.slice(0,7);close();persist();toast('근무 기록을 저장 중입니다.')},old&&isWorked(old)?()=>{modal('출근 전으로 되돌릴까요?','출근 표시만 취소하고 캘린더의 근무는 남겨 둡니다.','<div class="field full">날짜·근무지·시간은 그대로 보관됩니다. 실제 급여에서만 제외되며, 근무 후 다시 출근 완료로 바꿀 수 있습니다.</div>','출근 취소',()=>{data=cancelAttendance(data,id);close();persist();toast('출근 전으로 변경했습니다. 캘린더의 일정은 유지됩니다.')})}:old?()=>{modal('일정을 삭제할까요?','출근 취소와 달리 이 날짜의 근무 자체를 삭제합니다.','<div class="field full">삭제할 일정이 맞는지 확인하세요. 다른 날짜의 반복 일정은 유지됩니다.</div>','일정 삭제',()=>{const existing=data.records.find(x=>x.id===id),workplace=place(existing?.place);if(workplace&&scheduledOn(workplace,existing.date))data.places=data.places.map(x=>x.id===workplace.id?excludeWorkDate(x,existing.date):x);data.records=data.records.filter(x=>x.id!==id);close();persist();toast('일정을 삭제했습니다.')})}:scheduledDate?()=>deleteScheduled(p.id,scheduledDate):null);
if(old)$('#delete').textContent=isWorked(old)?'출근 취소':'일정 삭제';
$('#modal select[name=place]').onchange=e=>{let p=place(e.target.value);for(let name of ['start','end','break','rate'])$(`#modal [name=${name}]`).value=p[name]};}
function deleteScheduled(pid,date){modal('이 날짜의 근무 삭제',date+'의 '+place(pid).name+' 근무를 삭제합니다.','<div class="field full">다른 날짜의 반복 근무와 근무지 정보는 유지됩니다. 이 날짜는 근무지 수정의 추가 휴무일에서 다시 복원할 수 있습니다.</div>','삭제하기',()=>{data.places=data.places.map(p=>p.id===pid?excludeWorkDate(p,date):p);close();persist();toast('이 날짜의 근무를 삭제했습니다.')})}
function openDay(date){let rs=data.records.filter(r=>r.date===date),plans=plannedPlaces(data,date);if(!rs.length&&!plans.length){editRecord(null,date);return}const d=$('#modal');d.innerHTML=`<h2>${date} 근무</h2><p>잘못 누른 출근은 아래 기록의 수정을 눌러 날짜·근무지·시간을 바꾸거나 출근 취소할 수 있습니다.</p>${plans.length?'<div class="planned-list">'+plans.map(p=>`<button data-plan="${p.id}"><b>${esc(p.name)}</b><span>${p.start} – ${p.end} · ${esc(p.location)}</span><small>근무 수정·삭제 →</small></button>`).join('')+'</div>':''}${rs.length?recordTable(rs):''}<div class="form-actions"><button id="cancel">닫기</button><button id="day-add" class="primary">기록 추가</button></div>`;$('#cancel').onclick=close;$('#day-add').onclick=()=>{close();editRecord(null,date)};d.querySelectorAll('[data-edit-record]').forEach(b=>b.onclick=()=>{close();editRecord(b.dataset.editRecord)});d.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{close();editRecord(null,date,b.dataset.plan,date)});d.showModal()}
function adjust(){let a=data.adjustments[month]||{allowance:0,deduction:0};modal(`${mlabel()} 수당·공제`,'입력한 금액이 해당 월의 전체 급여에 반영됩니다.',field('추가 수당 (원)','allowance','number',a.allowance,'required min="0" max="1000000000" step="1"')+field('공제 금액 (원)','deduction','number',a.deduction,'required min="0" max="1000000000" step="1"')+'<p class="hint field full">주휴·연장수당, 세금·보험료 등 적용할 금액을 직접 합산해 입력하세요. 이 앱은 자동 세금 계산기가 아닙니다.</p>','적용하기',f=>{data.adjustments[month]={allowance:Number(f.get('allowance')),deduction:Number(f.get('deduction'))};close();persist();toast('수당과 공제를 반영했습니다.')})}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(){const cell=v=>'"'+String(v).replaceAll('"','""').replace(/^[=+@-]/,"'$&")+'"';let rr=rows(),a=data.adjustments[month]||{allowance:0,deduction:0},total=Math.round(rr.reduce((s,r)=>s+pay(r),0));let lines=[['근무일','근무지','출근','퇴근','휴게(분)','근무시간','시급','기본급여','메모','근무상태'],...rr.map(r=>[r.date,place(r.place)?.name,r.start,r.end,r.break,hrs(hours(r)),r.rate,pay(r).toFixed(2),r.note,isWorked(r)?'출근 완료':'출근 전']),[],['기본급여 합계',total],...(filter==='all'?[['추가 수당',a.allowance],['공제',a.deduction],['예상 수령액',total+a.allowance-a.deduction]]:[])];download(`월급하루-${month}.csv`,'\ufeff'+lines.map(l=>l.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('CSV 파일을 내보냈습니다.')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.closest('dialog'))return;if(b.hasAttribute('data-admin-users')){void adminUsers();return}if(b.dataset.annualStep){incomeYear=Math.max(2000,Math.min(2100,incomeYear+Number(b.dataset.annualStep)));render();return}if(b.dataset.incomeMonth){month=b.dataset.incomeMonth;view='salary';filter='all';render();window.scrollTo(0,0);return}if(b.dataset.view){view=b.dataset.view;filter='all';render();window.scrollTo(0,0)}else if(b.dataset.calendarPlan)editRecord(null,b.dataset.workDate,b.dataset.calendarPlan,b.dataset.workDate);else if(b.dataset.date)openDay(b.dataset.date);else if(b.dataset.editPlace)editPlace(b.dataset.editPlace);else if(b.dataset.editRecord)editRecord(b.dataset.editRecord);else if(b.dataset.addAt)editRecord(null,today(),b.dataset.addAt);else{switch(b.dataset.action){case 'refresh-dates':b.disabled=true;b.textContent='확인 중…';void syncHolidays(month.slice(0,4),true);break;case 'add-record':editRecord();break;case 'today':openDay(today());break;case 'add-place':editPlace();break;case 'all-places':allPlaces();break;case 'prev':case 'next':{let [y,m]=month.split('-').map(Number),d=new Date(y,m-1+(b.dataset.action==='prev'?-1:1),1);if(d.getFullYear()<2000||d.getFullYear()>2100)return;month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render();break}case 'adjust':adjust();break;case 'csv':csv();break;case 'backup':download(`월급하루-백업-${today()}.json`,JSON.stringify(data,null,2),'application/json');break;case 'restore':$('#restore-file').click();break;case 'start-own':modal('나의 기록을 시작할까요?','샘플 근무지와 기록을 지우고 빈 공간에서 시작합니다.','<div class="field full">새 근무지를 등록해 시급과 근무시간을 설정해 주세요.</div>','시작하기',()=>{data={version:1,sample:false,places:[],records:[],adjustments:{}};view='places';close();persist();toast('새로운 기록을 시작합니다.');editPlace()});break}}});
document.addEventListener('change',async e=>{if(e.target.hasAttribute('data-annual-place')){if(e.target.checked)annualExcluded.delete(e.target.dataset.annualPlace);else annualExcluded.add(e.target.dataset.annualPlace);render();return}if(e.target.id==='annual-select-all'){annualExcluded=e.target.checked?new Set():new Set([...document.querySelectorAll('[data-annual-place]')].map(input=>input.dataset.annualPlace));render();return}if(e.target.id==='annual-year'){incomeYear=Number(e.target.value);render();return}if(e.target.hasAttribute('data-salary-place')){if(e.target.checked)salaryExcluded.delete(e.target.dataset.salaryPlace);else salaryExcluded.add(e.target.dataset.salaryPlace);render();return}if(e.target.id==='salary-select-all'){salaryExcluded=e.target.checked?new Set():new Set(data.places.map(p=>p.id));render();return}if(e.target.type==='month'){if(/^\d{4}-\d{2}$/.test(e.target.value)&&e.target.validity.valid){month=e.target.value;render()}}if(e.target.id==='place-filter'){filter=e.target.value;render()}if(e.target.id==='restore-file'){try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('2MB 이하의 백업 파일을 선택해 주세요.');let next=JSON.parse(await file.text());validateBackup(next);modal('백업을 가져올까요?',`근무지 ${next.places.length}개, 기록 ${next.records.length}개를 불러옵니다. 현재 기록은 교체됩니다.`,'<div class="field full">현재 기록이 백업 내용으로 교체됩니다. 필요한 기록은 먼저 백업해 주세요. 비밀번호와 복구키는 변경되지 않습니다.</div>','가져오기',()=>{data=next;close();persist();toast('백업 기록을 불러왔습니다.')})}catch(err){toast(err.message||'백업 파일을 확인해 주세요.')}e.target.value=''}});
function validateBackup(v){return validateData(v);}
void boot();

let authMode='login';
function authPage(mode='login',message=''){
 authMode=mode;
 const signup=mode==='signup',recover=mode==='recover';
 $('#app').innerHTML=`<div class="auth-page"><div class="auth-art"><a class="brand" href="/"><img src="/favicon.svg" alt="">월급하루<span>.</span></a><div><p class="eyebrow">YOUR TIME, YOUR OWN STORY</p><h1>하루의 기록이 모여,<br>나의 월급이 되도록.</h1><p>일하는 곳도, 시간도 달라도.<br>나만의 공간에서 한 달의 가치를 확인하세요.</p><div class="auth-illustration"><div class="illustration-date">MY WORKSPACE <span>✓</span></div><b>차곡차곡, 나의 하루</b><div class="illustration-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><small>오늘도 수고한 나에게 든든한 기록 하나.</small></div></div><small>월급하루. 하루의 가치를 담다.</small></div><section class="auth-form-wrap"><div class="auth-form-card"><p class="eyebrow">WELCOME TO YOUR WORKSPACE</p><h2>${signup?'나만의 월급하루 시작하기':recover?'비밀번호 다시 설정하기':'다시 만나서 반가워요.'}</h2><p class="auth-intro">${signup?'아이디를 만들고, 나의 근무 기록을 시작하세요.':recover?'가입할 때 보관한 복구 키를 입력해 주세요.':'로그인하고 나의 근무와 월급을 확인하세요.'}</p><div class="auth-tabs" ${recover?'hidden':''}><button type="button" data-auth-mode="login" class="${signup?'':'selected'}">로그인</button><button type="button" data-auth-mode="signup" class="${signup?'selected':''}">회원가입</button></div>${localMode?'<p class="local-storage-notice">이 기기·브라우저에서만 사용하는 계정입니다. 기존 localhost 계정과 자동 연결되지 않습니다. 처음 이용하면 회원가입 후 기존 근무기록 백업을 가져와 주세요. 새로고침해도 로그인은 유지되며, 일반적으로 탭을 닫으면 종료됩니다. 탭 복원 시 로그인이 유지될 수 있으니 확실히 잠그려면 로그아웃을 눌러 주세요.</p>':''}<form id="auth-form">${signup?field('이름 또는 별명','name','text','','required maxlength="40" autocomplete="nickname"',true):''}${field('아이디','username','text','','required minlength="4" maxlength="24" pattern="[a-zA-Z][a-zA-Z0-9_]{3,23}" autocapitalize="none" spellcheck="false" autocomplete="username"',true)}${signup?'<p class="auth-hint">영문으로 시작하는 4~24자의 영문·숫자·밑줄</p>':''}${recover?field('복구 키','recoveryKey','text','','required maxlength="100" autocomplete="off" spellcheck="false"',true):''}${field(recover?'새 비밀번호':'비밀번호','password','password','',`required maxlength="128" ${signup||recover?'minlength="8"':''} autocomplete="${signup||recover?'new-password':'current-password'}"`,true)}${signup||recover?field('비밀번호 확인','passwordConfirm','password','','required minlength="8" maxlength="128" autocomplete="new-password"',true):''}${signup||recover?'<p class="auth-hint">비밀번호는 8자 이상 입력해 주세요. 문장 형태도 좋아요.</p>':''}<div id="auth-error" class="error" role="alert">${esc(message)}</div><button class="primary auth-submit" type="submit">${signup?'회원가입':recover?'새 비밀번호 설정':'로그인'} ${ico('arrow')}</button></form><button class="ghost auth-recover" data-auth-mode="${recover?'login':'recover'}">${recover?'로그인으로 돌아가기':'비밀번호를 잊으셨나요?'}</button><p class="auth-footnote">${signup?'복구키는 비밀번호 초기화에 필요합니다. 반드시 파일로 저장하고 안전하게 보관하세요.':recover?'복구 후 새 복구키가 발급되며 이전 복구키는 사용할 수 없습니다.':localMode?'브라우저 데이터 삭제·기기 변경에 대비해 백업 파일을 보관하세요.':'각 계정의 근무 기록은 해당 계정에서만 확인할 수 있습니다.'}</p></div></section></div>`;
 document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>authPage(b.dataset.authMode));
 $('#auth-form').onsubmit=async e=>{
   e.preventDefault();const form=e.target,f=new FormData(form),submit=form.querySelector('[type=submit]');
   if((signup||recover)&&f.get('password')!==f.get('passwordConfirm')){$('#auth-error').textContent='비밀번호 확인이 일치하지 않습니다.';return;}
   submit.disabled=true;submit.textContent='확인 중…';$('#auth-error').textContent='';
   try{
     const result=await api('/api/auth/'+(signup?'register':recover?'recover':'login'),'POST',Object.fromEntries(f));
     setAuth(result);if(currentUser.mustChangePassword){changePasswordPage();return}if(result.recoveryKey)showRecoveryKey(result.recoveryKey);await loadWorkspace();
   }catch(err){const target=$('#auth-error');if(target)target.textContent=err.message;submit.disabled=false;submit.textContent=signup?'회원가입':recover?'새 비밀번호 설정':'로그인';}
 };
}
async function loadWorkspace(){
 const result=await api('/api/workspace');data=validateData(result.data);revision=result.revision;salaryExcluded.clear();annualExcluded.clear();selectionMonth=month;pendingSnapshot=null;conflict=false;authExpired=false;saveState='saved';filter='all';view='dashboard';await syncHolidays(month.slice(0,4));render();updateSaveStatus();
}
async function boot(){
 try{setAuth(await api('/api/auth/session'));if(currentUser.mustChangePassword){changePasswordPage();return}await loadWorkspace();}
 catch(err){setAuth(null);authPage('login',err.status===401?'':err.message);}
}
function adminShell(){return '<section class="admin-screen"><div class="admin-toolbar"><label class="field">회원 검색<input id="admin-search" type="search" placeholder="아이디 또는 이름" value="'+esc(adminState.query)+'" autocomplete="off"></label><span id="admin-count"></span><button id="admin-refresh">목록 새로고침</button></div><div class="admin-layout"><section class="panel"><div class="panel-header"><h2>회원 목록</h2></div><div id="admin-members"></div></section><section class="panel admin-detail" id="admin-detail"></section></div></section>'}
async function adminUsers(){if(!currentUser?.isAdmin)return;view='admin';adminState.loading=true;adminState.error='';render();try{const result=await api('/api/admin/users');adminState.users=result.users;if(!result.users.some(u=>u.id===adminState.selectedId))adminState.selectedId=null;}catch(err){adminState.error=err.message;}finally{adminState.loading=false;if(view==='admin'){renderAdminRows();renderAdminDetail();}}}
function bindAdminShell(){const search=$('#admin-search');search.oninput=()=>{adminState.query=search.value;adminState.page=1;renderAdminRows()};$('#admin-refresh').onclick=()=>void adminUsers();$('#admin-members').onclick=e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.member){adminState.selectedId=button.dataset.member;renderAdminRows();renderAdminDetail()}else if(button.dataset.adminPage){adminState.page=Number(button.dataset.adminPage);renderAdminRows()}};renderAdminRows();renderAdminDetail()}
function renderAdminRows(){const list=$('#admin-members');if(!list)return;$('#admin-refresh').disabled=adminState.loading;const query=adminState.query.trim().toLocaleLowerCase(),users=adminState.users.filter(u=>(u.username+' '+u.name).toLocaleLowerCase().includes(query)),pages=Math.max(1,Math.ceil(users.length/20));adminState.page=Math.min(adminState.page,pages);$('#admin-count').textContent=users.length+'명 / 전체 '+adminState.users.length+'명';if(adminState.loading){list.innerHTML='<div class="blank">회원 목록을 불러오고 있습니다.</div>';return}if(adminState.error){list.innerHTML='<div class="error admin-list-error">'+esc(adminState.error)+'</div>';return}list.innerHTML=users.slice((adminState.page-1)*20,adminState.page*20).map(u=>`<div class="admin-member-row"><button class="admin-member ${adminState.selectedId===u.id?'selected':''}" data-member="${u.id}" aria-pressed="${adminState.selectedId===u.id}"><span><b>${esc(u.name)}</b><small>${esc(u.username)}</small></span><span class="member-badge">${u.isAdmin?'관리자':u.mustChangePassword?'비밀번호 변경 필요':'일반 회원'}</span></button>${u.isAdmin?'':`<button class="member-reset-action" data-member="${u.id}">비밀번호 변경</button>`}</div>`).join('')||'<div class="blank">검색 결과가 없습니다.</div>';if(pages>1)list.innerHTML+=`<div class="admin-pagination"><button data-admin-page="${Math.max(1,adminState.page-1)}" ${adminState.page===1?'disabled':''}>이전</button><span>${adminState.page} / ${pages}</span><button data-admin-page="${Math.min(pages,adminState.page+1)}" ${adminState.page===pages?'disabled':''}>다음</button></div>`}
function renderAdminDetail(){const detail=$('#admin-detail');if(!detail)return;const user=adminState.users.find(u=>u.id===adminState.selectedId);if(!user){detail.innerHTML='<div class="blank">왼쪽 회원 목록에서<br>관리할 회원을 선택해 주세요.</div>';return}detail.innerHTML='<h2>'+esc(user.name)+'</h2><p class="admin-identity">아이디: '+esc(user.username)+'</p>'+(user.isAdmin?'<p class="section-note">관리자 계정은 이 화면에서 초기화할 수 없습니다.</p>':'<h3>비밀번호 초기화</h3><p class="admin-help">기본값 dream을 그대로 사용하거나 다른 임시 비밀번호를 입력하세요.</p><form id="admin-reset-form"><div class="form-grid">'+field('새 임시 비밀번호','temporaryPassword','text','dream','required minlength="5" maxlength="128" autocomplete="off"',true)+'</div><p class="hint">임시 비밀번호는 5자 이상이며 24시간 유효합니다.<br>회원의 기존 로그인과 복구 키는 폐기되고 근무기록은 유지됩니다.<br>회원은 로그인 후 8자 이상의 새 비밀번호를 설정해야 합니다.</p><div class="error" role="alert"></div><button class="primary" type="submit">비밀번호 초기화</button></form>');if(user.isAdmin)return;$('#admin-reset-form').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form),error=form.querySelector('.error'),submit=form.querySelector('[type=submit]');submit.disabled=true;error.textContent='';try{const result=await api('/api/admin/users/'+user.id+'/reset-password','POST',{temporaryPassword:f.get('temporaryPassword')});user.mustChangePassword=true;user.tempPasswordExpiresAt=result.expiresAt;if(view!=='admin'||adminState.selectedId!==user.id){toast(user.name+' 님의 비밀번호를 초기화했습니다.');return}renderAdminRows();detail.innerHTML='<h2>초기화 완료</h2><p class="admin-identity">'+esc(user.name)+' · '+esc(user.username)+'</p><p class="admin-help">입력한 임시 비밀번호를 회원에게 직접 전달해 주세요.</p><label class="field">임시 비밀번호<input readonly value="'+esc(result.temporaryPassword)+'" autocomplete="off"></label><p class="hint">유효기한: '+new Date(result.expiresAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+'<br>회원은 로그인 후 새 비밀번호를 설정해야 합니다.</p><button id="admin-done">확인</button>';$('#admin-done').onclick=renderAdminDetail;}catch(err){if(form.isConnected){error.textContent=err.message;submit.disabled=false;}}};}
function changePasswordPage(){
$('#app').innerHTML='<section class="forced-password"><div class="panel"><h1>새 비밀번호 설정</h1><p>관리자가 비밀번호를 초기화했습니다. 나만의 새 비밀번호를 설정한 뒤 이용해 주세요.</p><form id="change-password-form">'+field('새 비밀번호','password','password','','required minlength="8" maxlength="128" autocomplete="new-password"',true)+field('비밀번호 확인','passwordConfirm','password','','required minlength="8" maxlength="128" autocomplete="new-password"',true)+'<div class="error" role="alert"></div><button class="primary" type="submit">새 비밀번호 저장</button></form><button class="ghost" data-logout>로그아웃</button></div></section>';
$('#change-password-form').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form),error=form.querySelector('.error'),submit=form.querySelector('[type=submit]');if(f.get('password')!==f.get('passwordConfirm')){error.textContent='비밀번호가 서로 다릅니다.';return}submit.disabled=true;try{const result=await api('/api/auth/change-password','POST',{password:f.get('password')});setAuth(result);await loadWorkspace();showRecoveryKey(result.recoveryKey);}catch(err){error.textContent=err.message;submit.disabled=false;}};
}
function profileView(){return '<div class="profile-grid"><section class="panel profile-card"><h2>기본 정보 변경</h2><p>현재 기기에 저장된 계정의 이름과 아이디를 변경합니다. 근무기록은 유지됩니다.</p><form id="profile-form"><div class="form-grid">'+field('이름 또는 별명','name','text',currentUser.name,'required maxlength="40" autocomplete="nickname"',true)+field('아이디','username','text',currentUser.username,'required minlength="4" maxlength="24" pattern="[a-zA-Z][a-zA-Z0-9_]{3,23}" autocapitalize="none" autocomplete="username"',true)+field('현재 비밀번호','currentPassword','password','','required maxlength="128" autocomplete="current-password"',true)+'</div><p class="hint">아이디를 변경하면 새 복구키가 발급되며 이전 복구키는 사용할 수 없습니다. 새 아이디와 복구키를 꼭 보관하세요.</p><div class="error" role="alert"></div><button type="submit" class="primary">정보 변경 저장</button></form></section><section class="panel profile-card"><h2>비밀번호 변경</h2><p>새 비밀번호는 8자 이상으로 설정하세요.</p><form id="profile-password-form"><div class="form-grid">'+field('현재 비밀번호','passwordCurrent','password','','required maxlength="128" autocomplete="current-password"',true)+field('새 비밀번호','newPassword','password','','required minlength="8" maxlength="128" autocomplete="new-password"',true)+field('새 비밀번호 확인','newPasswordConfirm','password','','required minlength="8" maxlength="128" autocomplete="new-password"',true)+'</div><p class="hint">변경 후 새 복구키가 발급되고 다른 창의 로그인은 종료됩니다. 새 복구키를 반드시 저장하세요.</p><div class="error" role="alert"></div><button type="submit" class="primary">비밀번호 변경</button></form></section></div>'}
function bindProfile(){for(const id of ['profile-form','profile-password-form']){const form=document.getElementById(id);form.onsubmit=async e=>{e.preventDefault();const values=new FormData(form),error=form.querySelector('.error'),button=form.querySelector('[type=submit]'),changingPassword=id==='profile-password-form';error.textContent='';if(changingPassword&&values.get('newPassword')!==values.get('newPasswordConfirm')){error.textContent='새 비밀번호 확인이 일치하지 않습니다.';return}button.disabled=true;try{await flushChanges();if(pendingSnapshot)throw Error('근무기록을 먼저 저장하거나 백업해 주세요.');const body=changingPassword?{currentPassword:values.get('passwordCurrent'),password:values.get('newPassword')}:{name:values.get('name'),username:values.get('username'),currentPassword:values.get('currentPassword')};const result=await api(changingPassword?'/api/auth/change-password':'/api/auth/profile','POST',body);setAuth(result);render();toast(changingPassword?'비밀번호를 변경했습니다. 새 복구키를 보관하세요.':'내 정보를 변경했습니다.');if(result.recoveryKey)showRecoveryKey(result.recoveryKey);}catch(err){if(form.isConnected){error.textContent=err.message;button.disabled=false;}}};}}
function backupView(){return '<section class="panel backup-screen"><h2>근무기록 백업</h2><p>근무지·일정·근무기록·수당·공제를 JSON 파일로 저장합니다. 다른 기기에서도 백업 파일을 가져올 수 있습니다.</p><div class="buttons"><button class="primary" data-action="backup">백업 파일 내보내기</button><button data-action="restore">백업 파일 가져오기</button></div><input type="file" id="restore-file" accept="application/json,.json" hidden><p class="backup-warning">백업 파일에는 급여와 근무기록이 암호화 없이 들어 있습니다. 다른 사람에게 공유하지 말고 안전한 곳에 보관하세요. 가져오면 현재 근무기록이 교체됩니다.</p><h2>비밀번호 복구</h2><p><b>복구키는 비밀번호 초기화에 필요하므로 반드시 따로 저장하세요.</b> 비밀번호를 잊으면 로그아웃 후 ‘비밀번호를 잊으셨나요?’에서 아이디·복구키·새 비밀번호를 입력하세요.</p><p>복구키와 근무기록 백업은 서로 다른 파일입니다. 백업 파일에는 비밀번호와 복구키가 포함되지 않습니다.</p>'+(localMode?'<p class="backup-warning">이 버전은 기록을 현재 브라우저에만 저장합니다. 브라우저 데이터를 삭제하면 계정과 기록도 삭제됩니다. 복구키만으로 삭제된 기록을 되살릴 수 없으므로 백업 파일도 꼭 보관하세요. 관리자 회원관리 기능은 제공하지 않습니다.</p>':'')+'</section>'}
function showRecoveryKey(key){
 modal('복구키를 반드시 저장해 주세요.','복구키는 비밀번호 초기화에 필요합니다. 이 창을 닫으면 다시 확인할 수 없으니 반드시 파일로 저장하고 안전하게 보관하세요.',`<div class="field full"><p class="recovery-warning">복구키를 분실하면 복구키를 이용한 비밀번호 초기화를 할 수 없습니다. 다른 사람에게 알려주지 마세요.</p><code class="recovery-key">${esc(key)}</code><button type="button" id="download-recovery">복구 키 파일로 보관</button><label class="recovery-check"><input type="checkbox" required> 복구 키를 별도로 보관했습니다.</label></div>`,'시작하기',()=>close());
 $('#download-recovery').onclick=()=>download('월급하루-계정복구키.txt',`월급하루 계정 복구 키\n아이디: ${currentUser.username}\n복구 키: ${key}\n\n비밀번호 초기화에 꼭 필요한 복구키입니다. 반드시 안전한 곳에 보관하고 다른 사람에게 공유하지 마세요. 새 복구키가 발급되면 이전 키는 사용할 수 없습니다. 근무기록 백업도 별도로 보관하세요.\n`,'text/plain;charset=utf-8');
 $('#cancel').hidden=true;$('#modal').oncancel=e=>e.preventDefault();$('#modal').addEventListener('close',()=>{$('#modal').oncancel=null;},{once:true});
}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.passwordToggle){const input=document.getElementById(b.dataset.passwordToggle);if(!input)return;const visible=input.type==='password';input.type=visible?'text':'password';b.textContent=visible?'숨기기':'보기';b.setAttribute('aria-pressed',String(visible));b.setAttribute('aria-label',b.dataset.passwordLabel+(visible?' 숨기기':' 보기'));return;}
 if(b.hasAttribute('data-retry-save')){b.disabled=true;await flushChanges();b.disabled=false;}
 if(b.hasAttribute('data-logout')){
   b.disabled=true;await flushChanges();
   if(pendingSnapshot){b.disabled=false;toast('저장되지 않은 기록이 있습니다. 다시 저장하거나 백업한 뒤 로그아웃해 주세요.');return;}
   try{await api('/api/auth/logout','POST',{});setAuth(null);data=emptyData();revision=0;close();authPage();}
   catch(err){if(err.status===401){setAuth(null);data=emptyData();close();authPage('login','로그인이 만료되었습니다. 다시 로그인해 주세요.');}else{toast(err.message);b.disabled=false;}}
 }
});
window.addEventListener('beforeunload',e=>{if(pendingSnapshot||savingPromise){e.preventDefault();e.returnValue='';}});

setInterval(()=>{if(currentUser)void syncHolidays(month.slice(0,4));},60000);
